typedef unsigned int nslSoundId;
typedef unsigned int nslSourceId;
typedef unsigned int nslEmitterId;
typedef float nlVector3d[3];

enum { NSL_INVALID_ID = 0, MAX_RANDOM_SOURCES = 50 };

class Random
{
public:
  int NextRand();
};

extern Random g_random;

inline float random()
{
  return (float)(unsigned int)g_random.NextRand() * (1.0f / 4294967296.0f);
}

inline int random(int n)
{
  return (unsigned int)g_random.NextRand() % n;
}

nslSoundId nslAddSound(nslSourceId source);
nslEmitterId nslCreateEmitter(nlVector3d &position);
void nslSetSoundEmitter(nslEmitterId emitter, nslSoundId sound);
void nslSetSoundRange(nslSoundId sound, float minDist, float maxDist);
void nslSetEmitterAutoRelease(nslEmitterId emitter);
void nslPlaySound(nslSoundId sound);

class RandomVO
{
private:
  float probability;
  nslSoundId thisSound;
  int totalSources;
  int numUsedSources;
  int numUnusedSources;
  bool valid;
  int lastSource;
  int probablity;
  nslEmitterId pos;
  nslSourceId sources[MAX_RANDOM_SOURCES];
  nslSourceId sourcesUsed[MAX_RANDOM_SOURCES];
  nslSourceId sourcesUnused[MAX_RANDOM_SOURCES];

public:
  int play3d(float x, float y, float z, float min, float max);
};

int RandomVO::play3d(float x, float y, float z, float min, float max)
{
  int index = 0;
  if (!valid) return NSL_INVALID_ID;
  if (totalSources == 0) return NSL_INVALID_ID;

  if (numUnusedSources == 0) {
    for (int i=0; i < totalSources; i++)
    {
      sourcesUnused[i] = sources[i];
      sourcesUsed[i] = NSL_INVALID_ID;
    }
    numUnusedSources = totalSources;
    numUsedSources = 0;
  }

  float val = random();
  if (val > probability)
    return NSL_INVALID_ID;

  int src = random(numUnusedSources);

  for (int i=0; i < totalSources; i++)
  {
    if (sources[i] == sourcesUnused[src])
      index = i;
  }
  lastSource = sourcesUnused[src];
  if (lastSource == NSL_INVALID_ID)
    return NSL_INVALID_ID;
  thisSound = nslAddSound(lastSource);
  if (thisSound == NSL_INVALID_ID)
    return NSL_INVALID_ID;
  sourcesUsed[numUsedSources++] = src;
  sourcesUnused[src] = sourcesUnused[--numUnusedSources];

  nlVector3d pos;
  pos[0] = x; pos[1] = y; pos[2] = z;

  nslEmitterId e = nslCreateEmitter(pos);
  nslSetSoundEmitter(e, thisSound);
  nslSetSoundRange(thisSound, min, max);
  nslSetEmitterAutoRelease(e);
  nslPlaySound(thisSound);

  return thisSound;
}
